    private string SecretOf(JsonObject r,Func<double> rng)
    {
        double Stat(string key)=>N(r["stats"],key);var secrets=new List<string>();if(Stat("greed")>=6)secrets.Add("I keep a few francs in a stocking in the chimney and tell nobody, not even at confession.");if(Stat("wealth")<=2)secrets.Add("I owe the baker for three weeks of bread and walk the long way round his shop.");if(Stat("piety")<=3)secrets.Add("I have not been to confession since Easter, and I do not miss it.");if(Stat("piety")>=7)secrets.Add("I have promised Our Lady a candle every Saturday if my wish is granted.");if(Stat("temper")>=7)secrets.Add("I said hard words to my brother at Easter and we have not spoken since. I would not be the first to give in.");if(Stat("courage")<=3)secrets.Add("I am afraid of the river at night and take the long way home to keep away from the quay.");if(Stat("gossip")>=7)secrets.Add("I told the whole street something I promised to keep to myself, and I am sorry for it.");secrets.Add("I am putting a little by for a passage to America, and nobody at home knows.");
        if(S(r,"family_role")is"single"or"lodger"){var pool=Residents().Where(o=>S(o,"sex")!=S(r,"sex")&&Math.Abs(N(o,"age")-N(r,"age"))<=6&&N(o,"age")>=16&&S(o,"family_role")is("single"or"lodger"or"son"or"daughter")&&N(o,"household")!=N(r,"household")).ToArray();int chosen=(int)Math.Floor(rng()*pool.Length);if(chosen>=0&&chosen<pool.Length){var other=pool[chosen];secrets.Add($"I think about {S(other,"name")} more than I should, and I have never said a word to {(S(other,"sex")=="f"?"her":"him")}.");}}return secrets[(int)Math.Floor(rng()*secrets.Count)];
    }
    private static string Hh(double hour){int h=(int)Math.Floor((hour%24+24)%24),minute=Round((hour-Math.Floor(hour))*60);return minute==0?h.ToString():$"{h}:{minute:00}";}
    public JsonArray DiaryFacts(JsonObject r,Func<double> rng)
    {
        var facts=new JsonArray();var work=A(r["sched"]?["day"]).FirstOrDefault(s=>s?[2]?.GetValue<string>()=="work");string label=S(data["tradeLabels"],S(r,"trade"),S(r,"trade").Replace('_',' '));facts.Add($"{S(r,"name")}, {N(r,"age")}, {label}, lives near {NearLabel(N(r["home"],"sx"),N(r["home"],"sz"))}."+(work==null?"":$" Works from {Hh(V(work[0]))} to {Hh(V(work[1]))} o'clock."));var tav=A(r["sched"]?["day"]).FirstOrDefault(s=>s?[2]?.GetValue<string>()=="tavern");if(tav!=null)facts.Add($"Most evenings at the tavern from {Hh(V(tav[0]))} o'clock.");if(A(r["sched"]?["sunday"]).Any(s=>s?[2]?.GetValue<string>()=="church"))facts.Add("Goes to mass at the cathedral on Sunday.");var family=Family(r).Take(5).ToArray();facts.Add(family.Length==0?"Lives alone.":"At home: "+string.Join(", ",family.Select(f=>$"{S(f,"name")} ({S(f,"family_role")}, {N(f,"age")})"))+".");if(r["dog"]!=null)facts.Add($"Has a {DogWords(S(r["dog"],"look"))} dog called {S(r["dog"],"name")}.");foreach(var memory in host.Rumours.Memories(S(r,"id"),4))facts.Add("Remembers: "+S(memory,"text"));facts.Add("Private: "+SecretOf(r,rng));return facts;
