    public static string[] EntryDates(int day,int count)=>Enumerable.Range(0,count).Select(i=>{int d=day-(count-1-i);return d>=1?Weekday(d):"last "+Weekday(d);}).ToArray();
    public static JsonArray EngineEntries(JsonArray facts,string[] dates)
    {
        var lines=facts.Select(f=>f!.GetValue<string>()).ToArray();var memories=lines.Where(s=>s.StartsWith("Remembers: ")).Select(s=>s[11..]).ToArray();string secret=lines.FirstOrDefault(s=>s.StartsWith("Private: "))?[9..]??"";var work=Regex.Match(lines.FirstOrDefault()??"",@"Works from (\S+) to (\S+) o'clock");var texts=new[]{work.Success?$"Up early. At work from {work.Groups[1]} to {work.Groups[2]}, as always. Tired feet.":"Up early. The same as every day. Tired feet.",memories.ElementAtOrDefault(0)??"Nothing much. Fog on the river all morning.",secret,memories.ElementAtOrDefault(1)??"Rain in the afternoon. Mended what needed mending.","Early to bed. God keep us all."}.Where(s=>s!="").ToArray();return new JsonArray(dates.Select((date,i)=>(JsonNode)new JsonObject{["date"]=date,["text"]=texts[i%texts.Length]}).ToArray());
    }
    public JsonObject CleanEntries(JsonArray facts,string[] dates,JsonObject output,JsonArray fallback)
    {
        string text=string.Join(" ",facts.Select(f=>f!.GetValue<string>())),lower=text.ToLowerInvariant();bool jef=Regex.IsMatch(text,@"\bJef\b");var numbers=DigitsOf(facts.Select(f=>f!.GetValue<string>()).ToArray());var names=Residents().Select(r=>S(r,"name").ToLowerInvariant()).ToArray();bool Good(string s)=>NumbersOk(s,numbers)&&!outOfWorld.IsMatch(s)&&(jef||!Regex.IsMatch(s,@"\bJef\b"))&&!names.Any(n=>s.ToLowerInvariant().Contains(n)&&!lower.Contains(n))&&!Regex.IsMatch(s,@"\b(knife|pistol|gun|blood|kill|murder|naked|bed with)\b",RegexOptions.IgnoreCase);var entries=new JsonArray();int valid=0;for(int i=0;i<dates.Length;i++){var authored=A(output["entries"]).FirstOrDefault(e=>N(e,"n")==i+1);string words=authored==null?"":NativeCoreInteriors.PlainEnglish(S(authored,"text"));bool good=words!=""&&Good(words);if(good)valid++;entries.Add(new JsonObject{["date"]=dates[i],["text"]=good?words:S(fallback[i],"text")});}return new(){["entries"]=entries,["ok"]=valid>=Math.Ceiling(dates.Length/2.0)};
    }
    private static readonly JsonObject diarySchema=Parse("""{"type":"object","properties":{"entries":{"type":"array","minItems":3,"maxItems":5,"items":{"type":"object","properties":{"n":{"type":"integer"},"text":{"type":"string","minLength":15,"maxLength":360}},"required":["n","text"]}}},"required":["entries"]}""");
    public async Task<JsonObject?> MaybeDiary(string? force=null,Func<double>? random=null)
    {
        await UnstickDiaries().ConfigureAwait(false);var prepare=await host.WithState(_=>{var rng=random??Random(unchecked((uint)((N(Town,"seed")==0?1873:N(Town,"seed"))*53+Day*3571)));if(force==null&&(Day<2||C.Scalar<int>("SELECT COUNT(*) FROM diary WHERE day=$p0",Day)>0||C.Scalar<int>("SELECT COUNT(*) FROM diary WHERE status IN('writing','lying')")>0||rng()>.5))return (JsonObject?)null;var had=C.Rows("SELECT owner FROM diary").Select(r=>S(r,"owner")).ToHashSet();var pool=Residents().Where(r=>N(r,"age")>=16&&!had.Contains(S(r,"id"))&&r["visitor"]==null&&S(r,"trade")is not("soldier"or"sentry"or"corporal"or"emigrant"or"runner"or"priest"or"infant")).ToArray();var r=force!=null&&force!="*"?Resident(force):pool.ElementAtOrDefault((int)Math.Floor(rng()*pool.Length));if(r==null)return null;var facts=DiaryFacts(r,rng);int count=(int)Math.Clamp(3+Math.Floor(rng()*3),3,5);var dates=EntryDates(Day,count);double angle=rng()*Math.PI*2;var drop=Snap?.Invoke(N(r["home"],"sx")+Math.Cos(angle)*2.2,N(r["home"],"sz")+Math.Sin(angle)*2.2,3);var p=drop!=null&&Reachable?.Invoke(drop.Value.X,drop.Value.Z)==true?Point(drop.Value.X,drop.Value.Z):Point(N(r["home"],"sx"),N(r["home"],"sz"));var fallback=EngineEntries(facts,dates);C.Execute("INSERT INTO diary(owner,day,x,z,facts_json,entries_json,source,status,started_min,tries)VALUES($p0,$p1,$p2,$p3,$p4,$p5,'engine','writing',$p6,1)",S(r,"id"),Day,Fixed(N(p,"x"),2),Fixed(N(p,"z"),2),facts.ToJsonString(),fallback.ToJsonString(),host.Clock.MinuteNow());return new JsonObject{["id"]=C.Scalar<int>("SELECT last_insert_rowid()"),["resident"]=r,["facts"]=facts,["dates"]=new JsonArray(dates.Select(s=>(JsonNode)JsonValue.Create(s)!).ToArray()),["fallback"]=fallback};});return prepare==null?null:await WriteDiary(prepare,true).ConfigureAwait(false);
    }
    private async Task<JsonObject?> WriteDiary(JsonObject prepare,bool useModel)
    {
        int id=(int)N(prepare,"id");long token=Interlocked.Increment(ref diaryToken);writingDiaries[id]=token;try{
            var request=await host.WithState(_=>useModel&&CanCallIdeas()?new JsonObject{["system"]=S(data,"diarySystem"),["prompt"]=$"The notebook of {S(prepare["resident"],"name")}.\n\nFACTS (engine; all true, all you may use)\n"+string.Join("\n",A(prepare["facts"]).Select(f=>"- "+f!.GetValue<string>()))+$"\n\nWRITE {A(prepare["dates"]).Count} entries, in order, one for each of: "+string.Join(", ",A(prepare["dates"]).Select(d=>d!.GetValue<string>()))+" (the engine puts the dates on them).\n- n: 1 to "+A(prepare["dates"]).Count+"; text: 1 to 3 short sentences. The private matter may come in once, quietly.",["schema"]=diarySchema.DeepClone(),["generation"]=generation}:new JsonObject{["generation"]=generation});JsonObject? output=null;if(request["schema"]!=null&&NarrateAsync!=null)try{output=await NarrateAsync(1,"diary",request).ConfigureAwait(false);}catch{/* Engine pages stand. */}
            return await host.WithState(_=>{if(generation!=N(request,"generation")||!writingDiaries.TryGetValue(id,out var live)||live!=token)return DiaryRow(id);var cleaned=output==null?null:CleanEntries(A(prepare["facts"]),A(prepare["dates"]).Select(n=>n!.GetValue<string>()).ToArray(),output,A(prepare["fallback"]));var entries=cleaned?["entries"]??prepare["fallback"]!;string source=B(cleaned,"ok")?"claude":"engine";if(C.Execute("UPDATE diary SET entries_json=$p0,source=$p1,status='lying' WHERE id=$p2 AND status='writing'",entries.ToJsonString(),source,id)==0)return DiaryRow(id);var diary=DiaryRow(id)!;var r=O(prepare["resident"]);Remember(1,S(r,"id"),"I have lost my notebook somewhere in the street. I hope nobody reads it.",4);Event("diary_lost",$"{S(r,"name")} lost a small notebook in the street near {NearLabel(N(diary,"x"),N(diary,"z"))}.",2,S(r,"id"));return diary;});
        }finally{((ICollection<KeyValuePair<int,long>>)writingDiaries).Remove(new(id,token));}
    }
    public async Task<JsonArray> UnstickDiaries()
    {
        var rows=await host.WithState(_=>C.Rows("SELECT * FROM diary WHERE status='writing'"));var done=new JsonArray();foreach(var row in rows){var prepare=await host.WithState(_=>{int id=(int)N(row,"id");bool leftOver=!writingDiaries.ContainsKey(id),old=row?["started_min"]==null||host.Clock.MinuteNow()-N(row,"started_min")>=30;if(!leftOver&&!old)return(JsonObject?)null;var r=Resident(S(row,"owner"));if(r==null){C.Execute("UPDATE diary SET status='gone',closed_day=$p0 WHERE id=$p1",Day,id);return null;}int tries=(int)N(row,"tries");C.Execute("UPDATE diary SET tries=$p0,started_min=$p1 WHERE id=$p2",tries+1,host.Clock.MinuteNow(),id);var fallback=A(JsonNode.Parse(S(row,"entries_json","[]")));return new JsonObject{["id"]=id,["resident"]=r,["facts"]=JsonNode.Parse(S(row,"facts_json","[]")),["dates"]=new JsonArray(fallback.Select(e=>(JsonNode)JsonValue.Create(S(e,"date"))!).ToArray()),["fallback"]=fallback,["retry"]=tries<2};});if(prepare==null)continue;await WriteDiary(prepare,B(prepare,"retry")).ConfigureAwait(false);done.Add(prepare["id"]!.DeepClone());}return done;
    }
    private void RegisterDiaries(NativeServiceHost service)
    {
        service.Register("GET","/api/diary/:id",r=>ReadDiary(r.PlayerId,int.Parse(r.Param("id"))));foreach(string action in new[]{"pick","return","sell","squeeze"})service.Register("POST","/api/diary/:id/"+action,r=>{int id=int.Parse(r.Param("id"));var at=At(r);var result=action switch{"pick"=>PickDiary(r.PlayerId,id,at),"return"=>ReturnDiary(r.PlayerId,id,at),"sell"=>SellDiary(r.PlayerId,id,at),_=>SqueezeDiary(r.PlayerId,id,at)};PushIdeas();PushJobs();return Reply(r.PlayerId,result);});
    }
